package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lcsvstream
#include "csv_stream.h"
#include <stdlib.h>

typedef int (*csv_stream_callback)(const char*, size_t, int, void*);
*/
import "C"
import (
    "fmt"
    "sync"
    "unsafe"
)

type streamContext struct {
    dataCh  chan string
    errCh   chan error
    mu      sync.Mutex
    active  bool
}

//export csvCallback
func csvCallback(json *C.char, length C.size_t, status C.int, ctx unsafe.Pointer) {
    sc := (*streamContext)(ctx)
    sc.mu.Lock()
    defer sc.mu.Unlock()

    if !sc.active {
        return
    }

    if status != 0 {
        sc.errCh <- fmt.Errorf("stream error: status=%d", status)
        return
    }

    if json == nil {
        close(sc.dataCh)
        sc.active = false
        return
    }

    goStr := C.GoStringN(json, C.int(length))
    C.free(unsafe.Pointer(json))
    sc.dataCh <- goStr
}

func StartCSVStream(path string) (<-chan string, <-chan error) {
    dataCh := make(chan string, 10)
    errCh := make(chan error, 1)

    ctx := &streamContext{
        dataCh: dataCh,
        errCh:  errCh,
        active: true,
    }

    go func() {
        cPath := C.CString(path)
        defer C.free(unsafe.Pointer(cPath))

        C.csv_stream(cPath, C.csv_stream_callback(C.csvCallback), unsafe.Pointer(ctx))

        ctx.mu.Lock()
        if ctx.active {
            close(errCh)
        }
        ctx.mu.Unlock()
    }()

    return dataCh, errCh
}

func main() {
    dataCh1, errCh1 := StartCSVStream("file1.csv")
    dataCh2, errCh2 := StartCSVStream("file2.csv")

    var wg sync.WaitGroup
    wg.Add(2)

    go func() {
        defer wg.Done()
        for json := range dataCh1 {
            fmt.Println("File1:", json)
        }
        for err := range errCh1 {
            fmt.Println("File1 Error:", err)
        }
    }()

    go func() {
        defer wg.Done()
        for json := range dataCh2 {
            fmt.Println("File2:", json)
        }
        for err := range errCh2 {
            fmt.Println("File2 Error:", err)
        }
    }()

    wg.Wait()
}
```

questions.question:
Design a CGOA wrapper for a C library exposing a tiny thread-safe in-memory key-value store with API:
- void kv_put(const char* key, const char* value);
- const char* kv_get(const char* key);
- void kv_free_result(const char* ptr);

The C layer stores copies of keys/values and kv_get returns a malloc’d string that must be freed with kv_free_result. Provide a header and a minimal C implementation using a small mutex-protected map. Then expose Go bindings with:
- func Put(key, value string) error
- func Get(key string) (string, error)
and a Go program that runs multiple goroutines performing puts and gets to test concurrency and memory ownership?

questions.explanation:
Why This Is Asked
- Tests CGO memory ownership, cross-language error handling, and basic concurrency.
- Ensures a candidate designs clean API boundaries between C and Go.

Key Concepts
- Memory ownership across CGO calls and explicit free paths.
- Thread-safety in C via mutex and in Go via goroutines.
- Minimal C header/implementation and Go bindings with proper error propagation.

Code Example
```javascript
// kv.h (C header)
void kv_put(const char* key, const char* value);
const char* kv_get(const char* key);
void kv_free_result(const char* ptr);
```
```javascript
// kv.c (C impl, minimal, thread-safe)
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include "kv.h"

static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
// Very small in-memory store as a linked list for simplicity
typedef struct Node { char* key; char* value; struct Node* next; } Node;
static Node* head = NULL;

static void insert_or_update(const char* k, const char* v) {
  Node* cur = head;
  while (cur) {
    if (strcmp(cur->key, k) == 0) { free(cur->value); cur->value = strdup(v); return; }
    cur = cur->next;
  }
  Node* n = malloc(sizeof(Node));
  n->key = strdup(k);
  n->value = strdup(v);
  n->next = head;
  head = n;
}

void kv_put(const char* key, const char* value) {
  pthread_mutex_lock(&mtx);
  insert_or_update(key, value);
  pthread_mutex_unlock(&mtx);
}

const char* kv_get(const char* key) {
  pthread_mutex_lock(&mtx);
  Node* cur = head;
  while (cur) {
    if (strcmp(cur->key, key) == 0) {
      char* ret = malloc(strlen(cur->value) + 1);
      strcpy(ret, cur->value);
      pthread_mutex_unlock(&mtx);
      return ret;
    }
    cur = cur->next;
  }
  pthread_mutex_unlock(&mtx);
  return NULL;
}

void kv_free_result(const char* ptr) { free((void*)ptr); }
